    "overview": "நெகம்போவிலிருந்து கற்பிட்டி, ஹபராணா, கண்டி, நுவரெலியா மற்றும் எல்லா வழியாகப் பயணம் செய்யுங்கள். கொழும்பிற்குச் செல்வதற்கு முன்பு யாலா, வெலிகமா மற்றும் பெந்தோட்டாவுக்குத் தொடருங்கள். இந்தப் பாதை சஃபாரிகள், பாரம்பரியத் தளங்கள், வெளிப்புறச் செயல்பாடுகள் மற்றும் கடற்கரை ஓய்வை இணைக்கிறது.",
