    "shortDescription": "பதின்ஏழு நாட்கள் மற்றும் பதினாறு இரவுகள், கலாச்சாரத் தலங்கள், மலைப்பகுதிக் காட்சிகள், வனவிலங்குகள் மற்றும் தெற்குக் கடற்கரைகள் ஆகியவற்றை உள்ளடக்கியது.",
    "overview": "ஹபரானா, சிгиரியா, ஹிரிவடுன்னா மற்றும் மின்னேரியா ஆகியவற்றை ஆராயுங்கள், மேலும் பலூன் சவாரி அனுபவத்துடனும் அனுராதபுரத்திற்குச் சென்று பார்வையிடுங்கள். தம்புள்ளை குகைக் கோயில், கண்டியின் பல் கோயில், ஒரு கலாச்சார நிகழ்ச்சி, அம்புலுவாவா கோபுரம் மற்றும் அரச தாவரவியல் பூங்காவைக் கண்டு மகிழுங்கள். நுவரெலியாவிற்குச் சென்று ரம்போடா நீர்வீழ்ச்சி, கிரிகோரி ஏரி மற்றும் ஒரு ஸ்ட்ராபெரித் தோட்டத்தையும், பின்னர் எல்லாவிற்குச் சென்று ஒன்பது வளைவுப் பாலம், மினி ஆடம்ஸ் பீக் மற்றும் ராவண நீர்வீழ்ச்சியையும் கண்டு மகிழுங்கள். தெற்குப் பகுதியில் யாலா தேசியப் பூங்கா, மிரிசா, கல்குடா டச்சுக் கோட்டை, கொஸ்கொட கடல் ஆமைகள் வளர்ப்பகம் மற்றும் பெந்தோட்டா சூரிய அஸ்தமனப் படகு சவாரி ஆகியவை இடம்பெற்றுள்ளன. கொழும்பு நகரப் பார்வை, ஷாப்பிங் மற்றும் தெருவோர உணவுகளுடன் உங்கள் பயணத்தை முடிக்கவும்.",
