    "shortDescription": "நெகோம்போ, ஹபராணா, கண்டி, நுவரெலியா மற்றும் எலா வழியாக பன்னிரண்டு நாட்கள் மற்றும் பதினொரு இரவுகள், காலி மற்றும் கொழும்பின் வழியாகத் திரும்பி.",
    "overview": "மினெரியா வனவிலங்குப் பார்வையை, ஹிரிவடுன்னா கிராமம், சிギリயா, ஒரு சூடான காற்று பலூன் அனுபவம் மற்றும் தம்புள்ளை குகைக் கோயில் ஆகியவற்றுடன் இணைத்துக்கொள்ளுங்கள். கண்டியில், புத்தரின் பல் கோயில் மற்றும் அம்புலுவாவா கோபுரத்தைப் பார்வையிட்டு, ஒரு கலாச்சார நிகழ்ச்சியை அனுபவிக்கவும். ஒரு தேயிலை ஆலைக்கும் எலா இடங்களுக்கும் தொடரவும்: ஒன்பது வளைவுப் பாலம், மினி ஆடம்ஸ் பிக் மற்றும் ராவண நீர்வீழ்ச்சி. கொழும்பு நகர சுற்றுலா மற்றும் ஷாப்பிங்கிற்கான நேரத்திற்கு முன்பு காலே டச்சு கோட்டையைப் பார்வையிடவும்.",
