    "shortDescription": "தேசியப் பூங்காக்கள், உயரமான பாதைகள், கிழக்குக் கடற்கரைகள் மற்றும் மழைக்காடுகள் வழியாக பதினேழு நாட்கள் பயணம் செய்து, தென்மேற்குக் கடற்கரையில் நேரத்தைச் செலவழித்து முடித்தேன்.",
    "overview": "தேசியப் பூங்காக்கள், உயரமான பாதைகள், கிழக்குக் கடற்கரைகள் மற்றும் மழைக்காடுகள் வழியாக பதினேழு நாட்கள் பயணம், இறுதியில் தென்மேற்குக் கடற்கரையில் நேரம் செலவழித்தல்.\n\nகீழே உள்ள பயணத்திட்டத்தில் உள்ள நிறுத்தங்களையும் செயல்பாடுகளையும் ஆராயுங்கள். சுற்றுலாப் பயணங்கள், கிடைப்பது, வானிலை மற்றும் உள்ளூர் சூழ்நிலைகளைப் பொறுத்தது.",
